    def maximumSum(self, nums: List[int]) -> int:
        # Helper function to get square-free part of a number
        def get_square_free_part(num):
            result = num
            d = 2
            while d * d <= result:
                while result % (d * d) == 0:
                    result //= (d * d)
                d += 1
            return result

        # Group numbers by their square-free part
        groups = defaultdict(list)

        for i, num in enumerate(nums):
            square_free = get_square_free_part(num)
            groups[square_free].append(num)

        # Calculate maximum sum: take the maximum element from each group
        max_sum = 0
        for group in groups.values():
            if len(group) > 0:
                max_sum = max(max_sum, max(group))

        return max_sum

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        # Input validation
        if not nums or target <= 0:
            return -1

        # Count frequency of each power of 2 in nums
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        # Convert target to binary representation to check bit by bit
        ops = 0

        # Process each bit position from highest to lowest (up to 31 bits)
        bit = 0
        while target > 0 and bit < 31:
            # Get current bit value
            bit_val = target & 1

            # If current bit is set, we need to provide this power of 2
            if bit_val == 1:
                # Check if we have this power of 2 available
                if bit in freq and freq[bit] > 0:
                    # Use one occurrence
                    freq[bit] -= 1
                else:
                    # Need to split larger elements to create this element
                    found = False
                    # Look for larger powers of 2 that can be split
                    for larger_bit in range(bit + 1, 31):
                        if larger_bit in freq and freq[larger_bit] > 0:
                            # Split one occurrence of larger_bit into two halves
                            freq[larger_bit] -= 1
                            # Add two occurrences of half the value
                            freq[larger_bit >> 1] = freq.get(larger_bit >> 1, 0) + 2
                            ops += 1
                            found = True
                            break

                    if not found:
                        return -1  # Impossible to reach target

            target >>= 1
            bit += 1

        return ops

