    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def helper(num):
            if num == 0:
                return 0

            num_str = str(num)
            n = len(num_str)

            memo = {}

            def dp(pos, tight, has_first, even_num, odd_num, mod_k):
                if pos == n:
                    return 1 if even_num == odd_num and mod_k == 0 else 0

                if (pos, tight, has_first, even_num, odd_num, mod_k) in memo:
                    return memo[(pos, tight, has_first, even_num, odd_num, mod_k)]

                res = 0
                bound = int(num_str[pos]) if tight else 9

                for i in range(0, bound + 1):
                    new_tight = tight and (i == bound)
                    new_has_first = has_first or (i > 0)

                    if not new_has_first:
                        new_even = even_num
                        new_odd = odd_num
                        new_mod = mod_k
                    else:
                        new_even = even_num + (1 if i % 2 == 0 else 0)
                        new_odd = odd_num + (1 if i % 2 == 1 else 0)
                        new_mod = (mod_k * 10 + i) % k

                    res += dp(pos + 1, new_tight, new_has_first, new_even, new_odd, new_mod)

                memo[(pos, tight, has_first, even_num, odd_num, mod_k)] = res
                return res

            return dp(0, True, False, 0, 0, 0)

        num_low = low - 1
        return helper(high) - helper(num_low)
